       (SELECT id FROM usuarios WHERE correo = 'supervisor@crmandino.pe'), v.i::date
FROM (VALUES ('Inventario de invierno', '{"sinProducto":"INV-01"}', 'Módulo Inventario con 15 % de descuento', 'INV-01', 15, '2026-06-10', '2026-07-10'),
